<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue'
import {Save,RefreshCw,SlidersHorizontal} from 'lucide-vue-next'
import {api,sessionNames,loadSessionNames} from '../api/account'
import {type MarketBook,type Quote,oddsMilli,oddsText} from '../api/markets'
const emit=defineEmits<{notify:[message:string]}>()
const session=ref('ssc-10'),book=ref<MarketBook|null>(null),editing=ref<Record<string,string>>({}),enabled=ref<Record<string,boolean>>({}),category=ref('all'),group=ref('all'),bulk=ref('1.960'),error=ref(''),busy=ref(false),loading=ref(false),dirty=ref(false)
let revision=0
const groups=computed(()=>[...new Set(book.value?.markets.map(m=>m.group)??[])])
const visible=computed(()=>book.value?.markets.filter(m=>(category.value==='all'||m.category===category.value)&&(group.value==='all'||m.group===group.value))??[])
async function load(){const v=++revision;loading.value=true;error.value='';try{const d=await api<MarketBook>(`/markets/${session.value}`);if(v!==revision)return;book.value=d;editing.value=Object.fromEntries(d.quotes.map(q=>[q.market_id,oddsText(q.odds_milli)]));enabled.value=Object.fromEntries(d.quotes.map(q=>[q.market_id,q.enabled]));dirty.value=false;group.value='all'}catch(e){if(v===revision)error.value=(e as Error).message}finally{if(v===revision)loading.value=false}}
watch(session,()=>void load());onMounted(()=>{void loadSessionNames();void load()})
function apply(){try{oddsMilli(bulk.value);for(const m of visible.value)editing.value[m.id]=bulk.value;dirty.value=true;error.value=''}catch(e){error.value=(e as Error).message}}
async function save(){if(!book.value)return;busy.value=true;error.value='';try{const quotes:Quote[]=book.value.markets.map(m=>({market_id:m.id,odds_milli:oddsMilli(editing.value[m.id]??''),enabled:enabled.value[m.id]??false}));await api(`/admin/markets/${session.value}`,'PUT',{quotes});dirty.value=false;emit('notify','该场次赔率已保存，旧订单保持原赔率')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="odds-admin"><section class="surface"><div class="surface-heading"><div><h3>场次赔率设置</h3><p class="form-hint">1.960 表示投注100中奖返还196（含本金）。每个位置、选项和场次可独立定价，支持三位小数。</p></div><span class="badge">新订单生效</span></div><div class="odds-filters"><label>选择场次<select v-model="session" :disabled="busy||dirty" aria-label="赔率场次"><option v-for="(name,id) in sessionNames" :key="id" :value="id">{{name}}</option></select></label><label>玩法类别<select v-model="category" aria-label="赔率玩法类别"><option value="all">全部玩法</option><option value="two_sides">两面（大小单双 / 龙虎）</option><option value="regular">常规（指定数字）</option></select></label><label>投注位置<select v-model="group" aria-label="赔率投注位置"><option value="all">全部位置</option><option v-for="g in groups" :key="g">{{g}}</option></select></label></div><div class="odds-bulk"><SlidersHorizontal :size="17"/><span>将当前筛选的 {{visible.length}} 项设置为</span><input v-model="bulk" aria-label="批量赔率" inputmode="decimal"/><button class="secondary-button" :disabled="busy||loading" @click="apply">应用到当前筛选</button></div><p class="form-hint">大小单双与龙虎初始为1.960。指定数字使用初始模板；PC蛋蛋不同和值概率不同，已分别给出初始赔率。请按你的运营规则调整。{{dirty?'当前有未保存修改，请保存或重新读取后切换场次。':''}}</p></section>
<div v-if="error" class="form-error" role="alert">{{error}}</div><p v-if="loading" class="loading-line">正在读取赔率…</p><section class="surface admin-data" v-if="book"><p class="mobile-table-hint">左右滑动查看完整规则与赔率</p><div class="data-table-wrap"><table class="data-table settings-table"><thead><tr><th>位置 / 玩法</th><th>选项</th><th>赔率（含本金）</th><th>接单</th><th>判定规则</th></tr></thead><tbody><tr v-for="m in visible" :key="m.id"><td>{{m.group}}<small>{{m.category==='two_sides'?'两面':'常规数字'}}</small></td><td><strong>{{m.label}}</strong></td><td><input v-model="editing[m.id]" :disabled="busy||loading" :aria-label="`${m.group}${m.label}赔率`" inputmode="decimal" @input="dirty=true"/></td><td><input type="checkbox" v-model="enabled[m.id]" :disabled="busy||loading" :aria-label="`${m.group}${m.label}接单`" @change="dirty=true"/></td><td class="odds-rule-cell">{{m.rule}}</td></tr></tbody></table></div></section><div class="settings-save"><span>{{sessionNames[session]}} · {{visible.length}} 项</span><div class="odds-save-actions"><button class="secondary-button" :disabled="busy||loading" @click="load"><RefreshCw :size="15"/>重新读取</button><button class="primary-button" :disabled="busy||loading" @click="save"><Save :size="15"/>{{busy?'保存中…':'保存场次赔率'}}</button></div></div></div></template>
